// Turn the request into hours per month, the number the priority is based on.
const r = $input.first().json;
const perMonth = { Daily: 21, Weekly: 4.33, Monthly: 1 };
const minutes = Number(r['Minutes each time']) || 0;
const people = Math.max(1, Number(r['People doing it']) || 1);
const hoursPerMonth = Math.round((minutes * (perMonth[r['How often']] ?? 1) * people / 60) * 10) / 10;
return [{ json: { ...r, minutes, people, hoursPerMonth } }];

