// Score the request and decide the priority. If the model failed, the request is still logged for manual triage.
const req = $('Hours per month').first().json;
const out = $input.first().json;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

let ai = null;
try {
  let text = out.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  ai = JSON.parse(text);
} catch (e) {
  ai = null;
}
const fits = ['high', 'medium', 'low'];
if (!ai || !fits.includes(ai.automation_fit)) {
  ai = { category: 'needs manual triage', automation_fit: 'unknown', summary: '', suggested_approach: 'The model did not answer. Triage by hand.', risk: '', question_for_requester: '' };
}

// Hours saved per month, discounted by how well the work suits automation.
const weight = { high: 1, medium: 0.6, low: 0.25, unknown: 0.5 }[ai.automation_fit];
const score = Math.round(req.hoursPerMonth * weight * 10) / 10;
const priority = score >= 10 ? 'P1' : score >= 3 ? 'P2' : 'P3';
const requestId = 'AR-' + String($execution.id).padStart(4, '0');

const row = {
  request_id: requestId,
  submitted_at: new Date().toISOString(),
  requester: String(req['Your name'] ?? ''),
  team: String(req['Team'] ?? ''),
  task: String(req['What do you do by hand today?'] ?? ''),
  tools: String(req['Tools involved'] ?? ''),
  frequency: String(req['How often'] ?? ''),
  minutes_each: req.minutes,
  people: req.people,
  hours_per_month: req.hoursPerMonth,
  category: String(ai.category ?? ''),
  automation_fit: ai.automation_fit,
  score,
  priority,
  suggested_approach: String(ai.suggested_approach ?? ''),
  risk: String(ai.risk ?? ''),
  question: String(ai.question_for_requester ?? ''),
  status: 'new',
};

const resultHtml = `
<h2>${esc(requestId)} logged, priority ${esc(priority)}</h2>
<p>${esc(ai.summary)}</p>
<p><b>Time spent today:</b> about ${esc(req.hoursPerMonth)} hours a month. <b>Fit for automation:</b> ${esc(ai.automation_fit)} (${esc(ai.category)}). <b>Score:</b> ${esc(score)}.</p>
<p><b>Suggested approach:</b> ${esc(ai.suggested_approach)}</p>
${ai.risk ? `<p><b>Watch out for:</b> ${esc(ai.risk)}</p>` : ''}
${ai.question_for_requester ? `<p><b>One question back to you:</b> ${esc(ai.question_for_requester)}</p>` : ''}`;

return [{ json: { row, resultHtml } }];
